"""Generated by AetherLab - numeric trajectory (curated component)."""

import numpy as np
from manim import *


class AetherLabScene(Scene):
    def construct(self):
        # AetherLab explanation layer: concept, governing equation, what to watch.
        _intro_head = Text('Numerical solution of the model', font_size=40, weight=BOLD, color=YELLOW)
        _intro_eq = Text("x' = v v' = -(stiffness/mass)*x - (2*damping)*v", font_size=30, color=WHITE)
        _intro_watch = Text('Watch: the tracer draws x(t) as time advances left to\nright.', font_size=26, color=GREY_B)
        _intro = VGroup(_intro_head, _intro_eq, _intro_watch).arrange(DOWN, buff=0.5)
        if _intro.width > 12.4:
            _intro.scale_to_fit_width(12.4)
        if _intro.height > 7.0:
            _intro.scale_to_fit_height(7.0)
        self.play(FadeIn(_intro, shift=0.2 * UP), run_time=1.0)
        self.wait(1.8)
        self.play(FadeOut(_intro), run_time=0.5)

        xs = [0.0, 0.16807, 0.33613, 0.5042, 0.67227, 0.84034, 1.0084, 1.17647, 1.34454, 1.51261, 1.68067, 1.84874, 2.01681, 2.18487, 2.35294, 2.52101, 2.68908, 2.85714, 3.02521, 3.19328, 3.36134, 3.52941, 3.69748, 3.86555, 4.03361, 4.20168, 4.36975, 4.53782, 4.70588, 4.87395, 5.04202, 5.21008, 5.37815, 5.54622, 5.71429, 5.88235, 6.05042, 6.21849, 6.38655, 6.55462, 6.72269, 6.89076, 7.05882, 7.22689, 7.39496, 7.56303, 7.73109, 7.89916, 8.06723, 8.23529, 8.40336, 8.57143, 8.7395, 8.90756, 9.07563, 9.2437, 9.41176, 9.57983, 9.7479, 9.91597, 10.08403, 10.2521, 10.42017, 10.58824, 10.7563, 10.92437, 11.09244, 11.2605, 11.42857, 11.59664, 11.76471, 11.93277, 12.10084, 12.26891, 12.43697, 12.60504, 12.77311, 12.94118, 13.10924, 13.27731, 13.44538, 13.61345, 13.78151, 13.94958, 14.11765, 14.28571, 14.45378, 14.62185, 14.78992, 14.95798, 15.12605, 15.29412, 15.46218, 15.63025, 15.79832, 15.96639, 16.13445, 16.30252, 16.47059, 16.63866, 16.80672, 16.97479, 17.14286, 17.31092, 17.47899, 17.64706, 17.81513, 17.98319, 18.15126, 18.31933, 18.48739, 18.65546, 18.82353, 18.9916, 19.15966, 19.32773, 19.4958, 19.66387, 19.83193, 20.0]
        ys = [1.0, 0.98614, 0.94587, 0.88158, 0.79622, 0.69318, 0.57616, 0.44906, 0.31586, 0.18054, 0.04691, -0.08145, -0.20125, -0.30963, -0.40417, -0.48296, -0.5446, -0.58824, -0.61357, -0.62079, -0.6106, -0.58413, -0.54291, -0.48879, -0.42391, -0.35056, -0.27119, -0.18826, -0.10424, -0.02149, 0.05778, 0.13157, 0.19812, 0.25595, 0.3039, 0.34114, 0.36718, 0.38184, 0.38529, 0.37798, 0.36065, 0.33425, 0.29997, 0.25913, 0.21317, 0.16362, 0.11201, 0.05986, 0.00862, -0.04033, -0.08576, -0.12661, -0.16197, -0.19113, -0.21362, -0.22912, -0.23757, -0.23907, -0.23393, -0.22261, -0.20573, -0.18403, -0.15833, -0.12955, -0.09863, -0.06651, -0.03415, -0.00244, 0.02778, 0.05575, 0.08082, 0.10242, 0.12016, 0.13371, 0.14293, 0.14777, 0.1483, 0.14474, 0.13737, 0.12659, 0.11286, 0.09671, 0.07869, 0.05939, 0.03941, 0.01933, -0.00029, -0.01894, -0.03615, -0.05153, -0.06473, -0.0755, -0.08367, -0.08914, -0.09189, -0.09198, -0.08953, -0.08475, -0.07787, -0.06919, -0.05904, -0.04776, -0.03573, -0.0233, -0.01085, 0.0013, 0.0128, 0.02339, 0.03282, 0.04088, 0.04742, 0.05234, 0.05557, 0.05712, 0.05703, 0.05537, 0.05227, 0.04789, 0.0424, 0.03603]

        title = Text('Damped oscillator: position follows the integrated motion.').scale(0.5).to_edge(UP)
        title.set_z_index(5)

        x_min, x_max = min(xs), max(xs)
        y_min, y_max = min(ys), max(ys)
        if y_max - y_min < 1e-9:
            y_min, y_max = y_min - 1.0, y_max + 1.0
        y_pad = (y_max - y_min) * 0.15

        axes = Axes(
            x_range=[x_min, x_max, (x_max - x_min) / 6.0],
            y_range=[y_min - y_pad, y_max + y_pad, (y_max - y_min) / 4.0],
            x_length=10,
            y_length=5,
            # layout: scaffolding recedes (dim) so the physics stays brightest.
            axis_config={"include_tip": False, "stroke_opacity": 0.35},
        ).to_edge(DOWN)
        axes.set_z_index(-5)
        x_label = axes.get_x_axis_label(Text("t").scale(0.4))
        y_label = axes.get_y_axis_label(Text('x').scale(0.4))
        x_label.set_z_index(5)
        y_label.set_z_index(5)

        points = [axes.coords_to_point(x, y) for x, y in zip(xs, ys)]
        curve = VMobject(color=BLUE)
        # Keep every solver sample as a path vertex so the rendered curve
        # cannot bow away from the numerical trajectory between samples.
        curve.set_points_as_corners(points)
        curve.set_z_index(0)
        tracer = Dot(points[0], color=YELLOW, radius=0.07)
        tracer.set_z_index(1)

        def point_at_time(alpha):
            # solve_numeric samples at uniform time intervals; interpolate by
            # sample index so tracer progress represents elapsed time, not
            # the path's changing arc length.
            position = np.clip(alpha, 0.0, 1.0) * (len(points) - 1)
            index = min(int(position), len(points) - 2)
            fraction = position - index
            return points[index] + fraction * (points[index + 1] - points[index])

        self.play(Create(axes), FadeIn(title), FadeIn(x_label), FadeIn(y_label), run_time=1.0)
        self.play(Create(curve), run_time=3.0)
        # Fade (don't pop) the tracer in so the eye tracks the handoff.
        self.play(FadeIn(tracer), run_time=0.4)
        self.play(
            UpdateFromAlphaFunc(
                tracer,
                lambda mob, alpha: mob.move_to(point_at_time(alpha)),
                rate_func=linear,
            ),
            run_time=2.5,
        )
        self.wait(0.5)

        # AetherLab explanation layer: clear the stage, then explain what it showed.
        for _m in self.mobjects:
            _m.clear_updaters()
        if self.mobjects:
            self.play(FadeOut(*self.mobjects), run_time=0.8)
        _head = Text('What the animation shows', font_size=34, weight=BOLD, color=YELLOW)
        _eq = Text("x' = v v' = -(stiffness/mass)*x - (2*damping)*v", font_size=28, color=WHITE)
        _facts = VGroup(Text('x starts at 1 and ends at 0.036 after t = 20', font_size=25, color=GREY_A), Text('Largest |x| reached: 1', font_size=25, color=GREY_A), Text('Parameters: damping = 0.15, stiffness = 1, mass = 1', font_size=25, color=GREY_A)).arrange(DOWN, aligned_edge=LEFT, buff=0.3)
        _key = Text('Every point on the curve comes from integrating the equations above\nnumerically, not from a sketch.', font_size=27, color=TEAL_A)
        _key_box = SurroundingRectangle(_key, color=TEAL, buff=0.22, corner_radius=0.12)
        _card = VGroup(_head, _eq, _facts, VGroup(_key, _key_box)).arrange(DOWN, buff=0.42)
        if _card.width > 12.4:
            _card.scale_to_fit_width(12.4)
        if _card.height > 7.0:
            _card.scale_to_fit_height(7.0)
        self.play(FadeIn(_head, shift=0.2 * DOWN), FadeIn(_eq), run_time=1.2)
        self.play(LaggedStart(*[FadeIn(_f, shift=0.2 * RIGHT) for _f in _facts], lag_ratio=0.85), run_time=4.2)
        self.play(FadeIn(_key), Create(_key_box), run_time=1.2)
        self.wait(1.8)
